float rawBatteryVoltage = 0;

float shuntVoltage_mV = 0;

float current_A = 0;
float filteredCurrent_A = 0;

float power_W = 0;

float peakDischarge_A = 0;
float peakCharge_A = 0;

// =====================================================
// BATTERY CAPACITY / SOC
// =====================================================

bool socSynchronized = false;

float remainingAh = 0;

// =====================================================
// SESSION DATA
// =====================================================

float sessionUsedAh = 0;
float sessionChargedAh = 0;

unsigned long sessionStartMillis = 0;

// =====================================================
// TIME TO EMPTY
// =====================================================

// Slow-moving average discharge current.
// Prevents TTE from jumping wildly.

float averageDischarge_A = 0;

const float TTE_ALPHA = 0.005;

// =====================================================
// TIMING
// =====================================================

const unsigned long SAMPLE_INTERVAL_MS = 100;
unsigned long lastSampleMillis = 0;

const unsigned long SAVE_INTERVAL_MS = 60000;
unsigned long lastSaveMillis = 0;

// =====================================================
// INA226 REGISTER READ
// =====================================================

bool readINA226Register(
  uint8_t reg,
  int16_t &value
) {

  Wire.beginTransmission(
    INA226_ADDRESS
  );

  Wire.write(reg);

  if (
    Wire.endTransmission(false) != 0
  ) {
    return false;
  }

  Wire.requestFrom(
    INA226_ADDRESS,
    (uint8_t)2
  );

  if (
    Wire.available() < 2
  ) {
    return false;
  }

  uint16_t raw =
    ((uint16_t)Wire.read() << 8) |
    Wire.read();

  value = (int16_t)raw;

  return true;
}

// =====================================================
// SHUNT VOLTAGE
// =====================================================

bool readShuntVoltage(
  float &millivolts
) {

  int16_t raw;

  if (
    !readINA226Register(
      0x01,
      raw
    )
  ) {
    return false;
  }

  millivolts =
    raw *
    INA226_SHUNT_LSB_V *
    1000.0;

  return true;
}

// =====================================================
// ADC SORT
// =====================================================

void sortValues(
  uint32_t values[],
  int count
) {

  for (
    int i = 0;
    i < count - 1;
    i++
  ) {

    for (
      int j = i + 1;
      j < count;
      j++
    ) {

      if (
        values[j] <
        values[i]
      ) {

        uint32_t temp =
          values[i];

        values[i] =
          values[j];

        values[j] =
          temp;
      }
    }
  }
}

// =====================================================
// BATTERY VOLTAGE
// =====================================================

float readBatteryVoltage() {

  const int SAMPLE_COUNT = 64;

  uint32_t samples[SAMPLE_COUNT];

  for (
    int i = 0;
    i < SAMPLE_COUNT;
    i++
  ) {

    samples[i] =
      analogReadMilliVolts(
        BATTERY_VOLTAGE_PIN
      );

    delayMicroseconds(150);
  }

  sortValues(
    samples,
    SAMPLE_COUNT
  );

  uint32_t total = 0;
  int count = 0;

  // Throw away highest/lowest readings

  for (
    int i = 12;
    i < 52;
    i++
  ) {

    total += samples[i];
    count++;
  }

  float sensorVoltage =
    (
      total /
      (float)count
    )
    /
    1000.0;

  return
    sensorVoltage *
    VOLTAGE_DIVIDER_RATIO *
    VOLTAGE_CALIBRATION;
}

// =====================================================
// SAVE BATTERY STATE
// =====================================================

void saveBatteryState() {

  preferences.begin(
    "battery",
    false
  );

  preferences.putBool(
    "synced",
    socSynchronized
  );

  preferences.putFloat(
    "remaining",
    remainingAh
  );

  preferences.end();

  lastSaveMillis =
    millis();
}

// =====================================================
// LOAD BATTERY STATE
// =====================================================

void loadBatteryState() {

  preferences.begin(
    "battery",
    true
  );

  socSynchronized =
    preferences.getBool(
      "synced",
      false
    );

  remainingAh =
    preferences.getFloat(
      "remaining",
      0
    );

  preferences.end();

  if (
    socSynchronized
  ) {

    remainingAh =
      constrain(
        remainingAh,
        0.0,
        BATTERY_CAPACITY_AH
      );
  }
}

// =====================================================
// SET FULL
// =====================================================

void setBatteryFull() {

  socSynchronized = true;

  remainingAh =
    BATTERY_CAPACITY_AH;

  sessionUsedAh = 0;
  sessionChargedAh = 0;

  peakDischarge_A = 0;
  peakCharge_A = 0;

  averageDischarge_A = 0;

  sessionStartMillis =
    millis();

  saveBatteryState();
}

// =====================================================
// SOC
// =====================================================

float getSOC() {

  if (
    !socSynchronized
  ) {

    return 0;
  }

  return
    (
      remainingAh /
      BATTERY_CAPACITY_AH
    )
    *
    100.0;
}

// =====================================================
// STATUS
// =====================================================

String batteryStatus() {

  if (
    filteredCurrent_A >
    0.10
  ) {

    return "DISCHARGING";
  }

  if (
    filteredCurrent_A <
    -0.10
  ) {

    return "CHARGING";
  }

  return "IDLE";
}

// =====================================================
// TIME TO EMPTY - HOURS
// =====================================================

float getTimeToEmptyHours() {

  if (
    !socSynchronized
  ) {

    return -1;
  }

  if (
    averageDischarge_A <
    0.10
  ) {

    return -1;
  }

  return
    remainingAh /
    averageDischarge_A;
}

// =====================================================
// UPDATE BATTERY MONITOR
// =====================================================

void updateBatteryMonitor() {

  unsigned long now =
    millis();

  if (
    now -
    lastSampleMillis <
    SAMPLE_INTERVAL_MS
  ) {

    return;
  }

  unsigned long elapsedMs =
    now -
    lastSampleMillis;

  lastSampleMillis =
    now;

  // ===================================================
  // VOLTAGE
  // ===================================================

  rawBatteryVoltage =
    readBatteryVoltage();

  if (
    batteryVoltage ==
    0
  ) {

    batteryVoltage =
      rawBatteryVoltage;
  }

  else {

    batteryVoltage =
      0.10 *
      rawBatteryVoltage
      +
      0.90 *
      batteryVoltage;
  }

  // ===================================================
  // CURRENT
  // ===================================================

  float newShunt;

  if (
    readShuntVoltage(
      newShunt
    )
  ) {

    shuntVoltage_mV =
      newShunt;

    current_A =
      (
        shuntVoltage_mV /
        1000.0
      )
      /
      SHUNT_OHMS;

    // -------------------------------------------------
    // ZERO DEADBAND
    // -------------------------------------------------

    if (
      fabs(current_A) <
      CURRENT_DEADBAND_A
    ) {

      current_A = 0;
    }

    // -------------------------------------------------
    // SMOOTH DISPLAY CURRENT
    // -------------------------------------------------

    filteredCurrent_A =
      0.25 *
      current_A
      +
      0.75 *
      filteredCurrent_A;

    // =================================================
    // DISCHARGING
    // =================================================

    if (
      current_A >
      0
    ) {

      if (
        current_A >
        peakDischarge_A
      ) {

        peakDischarge_A =
          current_A;
      }

      // Slow moving average for TTE

      if (
        averageDischarge_A ==
        0
      ) {

        averageDischarge_A =
          current_A;
      }

      else {

        averageDischarge_A =
          TTE_ALPHA *
          current_A
          +
          (
            1.0 -
            TTE_ALPHA
          )
          *
          averageDischarge_A;
      }
    }

    // =================================================
    // CHARGING
    // =================================================

    if (
      current_A <
      0
    ) {

      float chargeCurrent =
        -current_A;

      if (
        chargeCurrent >
        peakCharge_A
      ) {

        peakCharge_A =
          chargeCurrent;
      }
    }

    // =================================================
    // AMP HOURS
    // =================================================

    float elapsedHours =
      elapsedMs /
      3600000.0;

    float deltaAh =
      current_A *
      elapsedHours;

    if (
      current_A >
      0
    ) {

      sessionUsedAh +=
        deltaAh;
    }

    else if (
      current_A <
      0
    ) {

      sessionChargedAh +=
        -deltaAh;
    }

    // =================================================
    // SOC
    // =================================================

    if (
      socSynchronized
    ) {

      // Positive discharge removes capacity
      // Negative charging restores capacity

      remainingAh -=
        deltaAh;

      remainingAh =
        constrain(
          remainingAh,
          0.0,
          BATTERY_CAPACITY_AH
        );
    }
  }

  // ===================================================
  // POWER
  // ===================================================

  power_W =
    batteryVoltage *
    filteredCurrent_A;

  // ===================================================
  // PERIODIC SOC SAVE
  // ===================================================

  if (
    socSynchronized &&
    (
      now -
      lastSaveMillis >=
      SAVE_INTERVAL_MS
    )
  ) {

    saveBatteryState();
  }
}

// =====================================================
// RESET SESSION
// =====================================================

void resetSession() {

  sessionUsedAh = 0;
  sessionChargedAh = 0;

  peakDischarge_A = 0;
  peakCharge_A = 0;

  averageDischarge_A = 0;

  sessionStartMillis =
    millis();
}

// =====================================================
// JSON API
// =====================================================

String buildStatusJSON() {

  float soc =
    getSOC();

  float tte =
    getTimeToEmptyHours();

  unsigned long runtime =
    (
      millis() -
      sessionStartMillis
    )
    /
    1000;

  String json = "{";

  json +=
    "\"synced\":";

  json +=
    socSynchronized ?
    "true" :
    "false";

  json += ",";

  json +=
    "\"soc\":" +
    String(soc,2) +
    ",";

  json +=
    "\"remainingAh\":" +
    String(remainingAh,3) +
    ",";

  json +=
    "\"voltage\":" +
    String(batteryVoltage,2) +
    ",";

  json +=
    "\"current\":" +
    String(filteredCurrent_A,2) +
    ",";

  json +=
    "\"power\":" +
    String(power_W,1) +
    ",";

  json +=
    "\"status\":\"" +
    batteryStatus() +
    "\",";

  json +=
    "\"avgDischarge\":" +
    String(averageDischarge_A,2) +
    ",";

  json +=
    "\"tteHours\":" +
    String(tte,3) +
    ",";

  json +=
    "\"usedAh\":" +
    String(sessionUsedAh,3) +
    ",";

  json +=
    "\"chargedAh\":" +
    String(sessionChargedAh,3) +
    ",";

  json +=
    "\"peakDischarge\":" +
