// =====================================================
// FORMAT TIME TO EMPTY
// =====================================================

function formatTTE(hours) {

  if (
    hours === null ||
    hours < 0 ||
    !isFinite(hours)
  ) {

    return "--";
  }

  if (
    hours > 999
  ) {

    return ">999 h";
  }

  const h =
    Math.floor(hours);

  const m =
    Math.floor(
      (hours-h)*60
    );

  return `${h}h ${String(m).padStart(2,'0')}m`;
}

