// =====================================================
// RETURN HOME
// =====================================================

void returnHome() {

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303,
    "text/plain",
    ""
  );
}

// =====================================================
// WEB SERVER
// =====================================================

void setupWebServer() {

  // ---------------------------------------------------
  // DASHBOARD
  // ---------------------------------------------------

  server.on(
    "/",
    HTTP_GET,
    []() {

      server.send(
        200,
        "text/html",
        mainPage
      );
    }
  );

  // ---------------------------------------------------
  // LIVE API
  // ---------------------------------------------------

  server.on(
    "/api/status",
    HTTP_GET,
    []() {

      server.sendHeader(
        "Cache-Control",
        "no-store"
      );

      server.send(
        200,
        "application/json",
        buildStatusJSON()
      );
    }
  );

  // ---------------------------------------------------
  // SET FULL
  // ---------------------------------------------------

  server.on(
    "/setfull",
    HTTP_GET,
    []() {

      setBatteryFull();

      returnHome();
    }
  );

  // ---------------------------------------------------
  // RESET SESSION
  // ---------------------------------------------------

  server.on(
    "/reset",
    HTTP_GET,
    []() {

      resetSession();

      returnHome();
    }
  );

  // ---------------------------------------------------
  // UPDATE PAGE
  // ---------------------------------------------------

  server.on(
    "/updatepage",
    HTTP_GET,
    []() {

      server.send(
        200,
        "text/html",
        updatePage
      );
    }
  );

  // ---------------------------------------------------
  // OTA UPLOAD
  // ---------------------------------------------------

  server.on(
    "/update",
    HTTP_POST,

    []() {

      bool success =
        !Update.hasError();

      server.send(
        success ?
          200 :
          500,

        "text/plain",

        success ?
          "UPDATE SUCCESSFUL - REBOOTING" :
          "UPDATE FAILED"
      );

      delay(1000);

      if (
        success
      ) {

        ESP.restart();
      }
    },

    []() {

      HTTPUpload& upload =
        server.upload();

      if (
        upload.status ==
        UPLOAD_FILE_START
      ) {

        if (
          !Update.begin(
            UPDATE_SIZE_UNKNOWN
          )
        ) {

          Update.printError(
            Serial
          );
        }
      }

      else if (
        upload.status ==
        UPLOAD_FILE_WRITE
      ) {

        if (
          Update.write(
            upload.buf,
            upload.currentSize
          )
          !=
          upload.currentSize
        ) {

          Update.printError(
            Serial
          );
        }
      }

      else if (
        upload.status ==
        UPLOAD_FILE_END
      ) {

        if (
          !Update.end(true)
        ) {

          Update.printError(
            Serial
          );
        }
      }
    }
  );

  server.begin();
}

// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(
    115200
  );

  // ---------------------------------------------------
  // ADC
  // ---------------------------------------------------

  pinMode(
    BATTERY_VOLTAGE_PIN,
    INPUT
  );

  analogReadResolution(
    12
  );

  // ---------------------------------------------------
  // INA226
  // ---------------------------------------------------

  Wire.begin(
    INA226_SDA_PIN,
    INA226_SCL_PIN
  );

  // ---------------------------------------------------
  // LOAD BATTERY STATE
  // ---------------------------------------------------

  loadBatteryState();

  // ---------------------------------------------------
  // WIFI
  // ---------------------------------------------------

  WiFi.mode(
    WIFI_STA
  );

  WiFi.config(
    local_IP,
    gateway,
    subnet
  );

  WiFi.begin(
    ssid,
    password
  );

  while (
    WiFi.status() !=
    WL_CONNECTED
  ) {

    delay(500);
  }

  // ---------------------------------------------------
  // TIMING
  // ---------------------------------------------------

  sessionStartMillis =
    millis();

  lastSampleMillis =
    millis();

  lastSaveMillis =
    millis();

  // ---------------------------------------------------
  // SERVER
  // ---------------------------------------------------

  setupWebServer();
}

// =====================================================
// LOOP
// =====================================================

void loop() {

  updateBatteryMonitor();

  server.handleClient();
}
